update public.pooja_steps set instruction_en = 'Offer the two cloths, then the mangalyam, then the ornaments. A small new blouse-piece and whatever gold the house has are what is usually used. This is the sequence that makes the kalasham a married woman of the household rather than a vessel.', updated_at = now()
