update public.pooja_steps set instruction_ta = 'இரண்டு வஸ்திரங்கள், பின் மாங்கல்யம், பின் ஆபரணங்கள் சமர்ப்பிக்கவும். பொதுவாக ஒரு புதிய ரவிக்கைத் துணியும், வீட்டில் உள்ள தங்க நகைகளும் பயன்படுத்தப்படுகின்றன. இந்த வரிசைதான் கலசத்தை ஒரு பாத்திரமாக அல்லாமல், வீட்டுச் சுமங்கலியாக ஆக்குகிறது.', updated_at = now()
