-- Dhoopam & Deepam: meaning was ten-ingredient incense and a darkness-destroying wick; the mantra is guggulu and aloe, and a lamp of three wicks.
update public.pooja_steps set meaning_en = 'I give you this pleasing incense, with guggulu and aloe: receive it, Mahalakshmi, who grant what your devotees wish. With ghee and three wicks, giver of all that is desired: receive this lamp, Kamala, and give me all that I long for. To Sri Varalakshmi, salutations: I offer the incense and show the lamp, and after them, water to sip.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhoopam & Deepam'
   and meaning_en is distinct from 'I give you this pleasing incense, with guggulu and aloe: receive it, Mahalakshmi, who grant what your devotees wish. With ghee and three wicks, giver of all that is desired: receive this lamp, Kamala, and give me all that I long for. To Sri Varalakshmi, salutations: I offer the incense and show the lamp, and after them, water to sip.';

-- Karpura Neerajanam: meaning was "the lamp is brought ... beloved of Vishnu"; the mantra is niraajanam nirajaskam.
update public.pooja_steps set meaning_en = 'This waving of light, without blemish, made by me with camphor: Lakshmi, I wave it before you, who light the worlds for ever. To Sri Varalakshmi, salutations: I show the camphor flame, and after it, water to sip.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Karpura Neerajanam'
