-- Pushpanjali & Mantra Pushpam: meaning was the old dhyana verse and philosophy said "the same verse as the dhyanam"; the mantra is the jaati-champaka pushpanjali.
update public.pooja_steps set meaning_en = 'With jati, champaka, punnaga, jasmine, vakula and other flowers I offer you a double handful of flowers: receive it, beloved of Hari. To Sri Varalakshmi, salutations: I offer the mantra-flower; I offer the golden flower.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pushpanjali & Mantra Pushpam'
