update public.pooja_steps set philosophy_en = 'Jati, jasmine and vakula were each named at the Gandham step and offered there one at a time. Here they come back in a single handful from both palms. The worship that began by itemising ends by giving everything at once.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pushpanjali & Mantra Pushpam'
   and philosophy_en is distinct from 'Jati, jasmine and vakula were each named at the Gandham step and offered there one at a time. Here they come back in a single handful from both palms. The worship that began by itemising ends by giving everything at once.';

-- Pradakshina: meaning and philosophy translated "papo'ham papakarmaham"; the mantra is sarvamangala laabhaaya ... namo'stu naaleeka nibhaananaayai.
update public.pooja_steps set meaning_en = 'For the gaining of everything auspicious and the turning away of every wrong, I go round you today: be gracious, supreme goddess. Salutations to her whose face is like the lotus; salutations to the beloved of Narayana; salutations to her who was born of the ocean; salutations to Lakshmi, mother of the worlds. To Sri Varalakshmi, salutations: I offer circumambulation and prostration.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pradakshina'
   and meaning_en is distinct from 'For the gaining of everything auspicious and the turning away of every wrong, I go round you today: be gracious, supreme goddess. Salutations to her whose face is like the lotus; salutations to the beloved of Narayana; salutations to her who was born of the ocean; salutations to Lakshmi, mother of the worlds. To Sri Varalakshmi, salutations: I offer circumambulation and prostration.';
update public.pooja_steps set philosophy_en = 'Sarvamangala labhaya, sarva papa nivrittaye, "for gaining every good, for the turning away of every wrong". The circuit asks for both in one breath, and it is recited while walking rather than sitting, so that the whole body does the asking and not only the voice.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pradakshina'
   and philosophy_en is distinct from 'Sarvamangala labhaya, sarva papa nivrittaye, "for gaining every good, for the turning away of every wrong". The circuit asks for both in one breath, and it is recited while walking rather than sitting, so that the whole body does the asking and not only the voice.';

-- Namaskaram & Varalakshmi Prarthana: meaning was "salutations to you, mother of the world" and philosophy argued from "lokajanani"; the mantra is aayuraarogyam aishvaryam and the royal courtesies.
update public.pooja_steps set meaning_en = 'Long life, health and prosperity, sons and grandsons, cattle and wealth, and the end of enemies: grant them, Mahalakshmi, treasury of compassion. The parasol and the fan, dance, song and music, and the rest: every courtesy, those within my means and those fit for a god, I offer to you.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana'
   and meaning_en is distinct from 'Long life, health and prosperity, sons and grandsons, cattle and wealth, and the end of enemies: grant them, Mahalakshmi, treasury of compassion. The parasol and the fan, dance, song and music, and the rest: every courtesy, those within my means and those fit for a god, I offer to you.';
update public.pooja_steps set philosophy_en = 'Chhatra, chamara, nritta, gita, vadya: the parasol, the fan, dance, song and music, the honours of a royal court. No household has these to give, so they are offered in words. The prayer just before them is plain about what the household wants: long life, health, children and grandchildren, cattle and wealth.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana'
   and philosophy_en is distinct from 'Chhatra, chamara, nritta, gita, vadya: the parasol, the fan, dance, song and music, the honours of a royal court. No household has these to give, so they are offered in words. The prayer just before them is plain about what the household wants: long life, health, children and grandchildren, cattle and wealth.';

-- Sharadu Dharanam: meaning asked for children and good fortune of "Rama"; the mantra receives the thread and ties it. Philosophy quoted "badhnami", the mantra says "badhniyam".
update public.pooja_steps set meaning_en = 'Auspiciousness of all auspicious things, destroyer of every wrong: I receive this thread; be well pleased always. Of nine strands, with nine knots: let me tie this thread on my right hand, beloved of Hari.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam'
   and meaning_en is distinct from 'Auspiciousness of all auspicious things, destroyer of every wrong: I receive this thread; be well pleased always. Of nine strands, with nine knots: let me tie this thread on my right hand, beloved of Hari.';
update public.pooja_steps set philosophy_en = 'Badhniyam dakshine haste, "let me tie it on the right hand". The verb is first person, because a vidhi text is written for whoever is reciting it; it is not a ruling that the tying must be done alone. In most Tamil households the husband ties it, with three knots, and the older women tie it for the girls. Nine knots were worshipped a moment ago and three are made now, and the two counts belong to different things: the nine are the thread, the three are the tying.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam'
   and philosophy_en is distinct from 'Badhniyam dakshine haste, "let me tie it on the right hand". The verb is first person, because a vidhi text is written for whoever is reciting it; it is not a ruling that the tying must be done alone. In most Tamil households the husband ties it, with three knots, and the older women tie it for the girls. Nine knots were worshipped a moment ago and three are made now, and the two counts belong to different things: the nine are the thread, the three are the tying.';

-- Vayana Dhanam: meaning was a rubric about twelve cakes; philosophy quoted "indira pratigrihnatu indirayai dadati". The mantra is the seat, the hiranyagarbha verse, "indira pratigrihnati indira vai dadati" and the upayana formula.
update public.pooja_steps set meaning_en = 'This seat is for the brahmana, who stands here in the form of Varalakshmi; this sandal and the rest are honoured with every worship. The golden seed of fire, held within Hiranyagarbha, gives the fruit of endless merit: so grant me peace. Indira receives, and Indira indeed gives; Indira carries both across: salutations, salutations to Indira. This gift, with dakshina and with betel, I give to you, and it is no longer mine, desiring the full fruit of the Varalakshmi pooja, long and happy married life, the increase of good sons and grandsons, and the favour of Varalakshmi.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
   and meaning_en is distinct from 'This seat is for the brahmana, who stands here in the form of Varalakshmi; this sandal and the rest are honoured with every worship. The golden seed of fire, held within Hiranyagarbha, gives the fruit of endless merit: so grant me peace. Indira receives, and Indira indeed gives; Indira carries both across: salutations, salutations to Indira. This gift, with dakshina and with betel, I give to you, and it is no longer mine, desiring the full fruit of the Varalakshmi pooja, long and happy married life, the increase of good sons and grandsons, and the favour of Varalakshmi.';
update public.pooja_steps set philosophy_en = 'Indira pratigrihnati, indira vai dadati cha, "Lakshmi receives, and Lakshmi gives". The verse refuses to let either party be the superior one, which is the only way a gift between neighbours survives being ritualised.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
   and philosophy_en is distinct from 'Indira pratigrihnati, indira vai dadati cha, "Lakshmi receives, and Lakshmi gives". The verse refuses to let either party be the superior one, which is the only way a gift between neighbours survives being ritualised.';

-- Ksheera Arghyam: meaning was a water-arghyam verse; the mantra is the sankalpa for the milk arghyam, and the verse itself lives in the archana row.
update public.pooja_steps set meaning_en = 'For the wearing away of every wrong I carry, for the pleasure of the supreme lord, and so that the fruit of the Varalakshmi pooja may be complete, I shall offer the arghyam of milk.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam'
   and meaning_en is distinct from 'For the wearing away of every wrong I carry, for the pleasure of the supreme lord, and so that the fruit of the Varalakshmi pooja may be complete, I shall offer the arghyam of milk.';

-- Udvasanam: meaning opened with the Purusha Sukta ("By sacrifice the gods sacrificed") and closed "peace, peace, peace"; the mantra is two lines of leave-taking.
update public.pooja_steps set meaning_en = 'From this vessel I return Sri Varalakshmi to her own place: for what is good, for well-being, and for her coming again.', updated_at = now()
 where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Udvasanam'
   and meaning_en is distinct from 'From this vessel I return Sri Varalakshmi to her own place: for what is good, for well-being, and for her coming again.';

-- Ksheera Arghyam archana 1: the verse is gokshirena yutam, not a water verse.
update public.archana_items set meaning_en = 'Mixed with cow''s milk, with sandal and flowers: receive this arghyam, goddess, giver of boons; Varalakshmi, salutations to you. To Sri Varalakshmi, salutations: this is the arghyam, this is the arghyam, this is the arghyam.'
 where pooja_step_id = (select id from public.pooja_steps
                         where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam')
   and seq = 1
   and meaning_en is distinct from 'Mixed with cow''s milk, with sandal and flowers: receive this arghyam, goddess, giver of boons; Varalakshmi, salutations to you. To Sri Varalakshmi, salutations: this is the arghyam, this is the arghyam, this is the arghyam.';

-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  -- Every field landed, which also proves every step title was found.
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Peeta Pooja' and meaning_en = 'Studded with many jewels: daughter of the ocean of milk, goddess, beloved of Hari, accept this golden throne. To Sri Varalakshmi, salutations: I offer the seat.';
  if n <> 1 then raise exception 'Peeta Pooja.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam' and meaning_en = 'Lakshmi, daughter of the king of the ocean of milk, queen of the house of Sri Ranga, served by all the wives of the gods as their maids, the one small flame that lights the world, by whose gentle glance Brahma, Indra and Shiva gained their glory: I salute you, born of the lotus, mistress of the household of the three worlds, dear to Mukunda. She who sits on the lotus, broad-hipped, with eyes as long as lotus petals, deep-navelled, full-breasted, in a white upper cloth; Lakshmi, bathed by the great elephants of heaven from golden pots set with jewels; lotus in hand and joined with every auspiciousness: may she always live in my house. Seated on the lotus, lotus in hand, garlanded with lotuses, risen from the ocean of milk, shining the colour of milk and dressed in cloth as white as milk, beloved of Hari: with devotion I picture her in this lovely kalasham. In this kalasham I meditate on Sri Varalakshmi.';
  if n <> 1 then raise exception 'Dhyanam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam' and philosophy_en = 'Mama vasatu grihe, "may she live in my house". The dhyanam asks for residence, not a visit, and asks it before she has even been invited. That is why the next day needs a step of its own to send her back: she was never asked to leave.';
  if n <> 1 then raise exception 'Dhyanam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam' and instruction_en = 'Close your eyes and hold the form in mind as the three verses draw it: risen from the ocean of milk, seated on the lotus with a lotus in her hand, bathed by elephants from golden pots, dressed in white, dear to Hari. The last line pictures her in this kalasham; she is invited two steps later, once the thread is in place. Done once, on the first day only.';
  if n <> 1 then raise exception 'Dhyanam.instruction_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam' and instruction_ta = 'கண்களை மூடி, மூன்று ஸ்லோகங்களும் வர்ணிக்கும் வடிவத்தை மனதில் நிறுத்தவும் — பாற்கடலில் தோன்றியவள், தாமரையில் அமர்ந்து கையில் தாமரை ஏந்தியவள், யானைகளால் பொற்குடங்களில் நீராட்டப்படுபவள், வெண்ணிற ஆடை அணிந்தவள், ஹரிக்குப் பிரியமானவள். கடைசி வரி அவளை இந்தக் கலசத்தில் தியானிக்கிறது; சரடு வைக்கப்பட்ட பின், இரண்டு படிகள் கழித்து ஆவாஹனம் செய்யப்படுகிறது. இது முதல் நாளில் மட்டும் ஒரு முறை.';
  if n <> 1 then raise exception 'Dhyanam.instruction_ta was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Padyam, Arghyam & Achamaniyam' and meaning_en = 'Brought from the Ganga and the other rivers, with sandal and flowers: I give you water for the feet, goddess; be gracious, supreme mistress. Brought from the river Ganga and held in a golden pot: receive the arghyam I give, you who grant the blessing of sons and grandsons. Clear, cool water, you whose lotus face is serene: receive it to sip, beloved of the one whose banner is Garuda. Mahalakshmi, great goddess, joined with honey, ghee and curd: receive this madhuparkam, beloved of Madhusudana. To Sri Varalakshmi, salutations: I offer each in turn.';
  if n <> 1 then raise exception 'Padyam, Arghyam & Achamaniyam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Padyam, Arghyam & Achamaniyam' and philosophy_en = 'The first three are older than any temple: they are what a household in a hot country did for anyone who reached the door. The madhuparkam, honey mixed with curd and ghee, is the honour beyond them, set before the guest the house most wished to receive. The pooja keeps all four unchanged.';
  if n <> 1 then raise exception 'Padyam, Arghyam & Achamaniyam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Padyam, Arghyam & Achamaniyam' and instruction_en = 'The courtesies given to any guest who arrives on foot: water for the feet, water for the hands, water to sip, and then the madhuparkam, honey and curd with ghee. Pour a spoonful into the uddharani at each and empty it into the plate.';
  if n <> 1 then raise exception 'Padyam, Arghyam & Achamaniyam.instruction_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Padyam, Arghyam & Achamaniyam' and instruction_ta = 'நடந்து வரும் விருந்தினருக்குச் செய்யும் உபசாரங்கள் — பாதம் கழுவ ஜலம், கை கழுவ ஜலம், பருக ஜலம், பின் தேனும் தயிரும் நெய்யும் கலந்த மதுபர்க்கம். ஒவ்வொன்றிலும் உத்தரிணியில் ஒரு ஸ்பூன் எடுத்து தாம்பாளத்தில் ஊற்றவும்.';
  if n <> 1 then raise exception 'Padyam, Arghyam & Achamaniyam.instruction_ta was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Panchamrita & Shuddhodaka Snanam' and meaning_en = 'Milk and curd with ghee, together with sugar and honey: receive this bath of the five nectars, Varalakshmi; salutations to you. Clear water held in a golden pot, brought from the Ganga and the other rivers: receive it for your bath, goddess, daughter of the ocean. To Sri Varalakshmi, salutations: I offer the bath, and after the bath, water to sip.';
  if n <> 1 then raise exception 'Panchamrita & Shuddhodaka Snanam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Panchamrita & Shuddhodaka Snanam' and philosophy_en = 'Gangadi saridahritam, "brought from the Ganga and the other rivers". Whatever is actually in the vessel, the sentence says what it is being treated as, and the treating is the rite.';
  if n <> 1 then raise exception 'Panchamrita & Shuddhodaka Snanam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vastram, Abharanam & Mangalyam' and meaning_en = 'A fine pair of heavenly garments and a lovely bodice: Varalakshmi, great goddess, receive what I offer. Set with the auspicious gem, with pearls and coral: receive the mangalasutra given to you, beloved of Hari. You who are adorned with jewelled earrings, armlets, necklaces and bangles: receive these precious ornaments, treasury of compassion. To Sri Varalakshmi, salutations: I offer the cloth, the thread for the neck, and the ornaments.';
  if n <> 1 then raise exception 'Vastram, Abharanam & Mangalyam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vastram, Abharanam & Mangalyam' and instruction_en = 'Offer the two cloths, then the mangalyam, then the ornaments. A small new blouse-piece and whatever gold the house has are what is usually used. This is the sequence that makes the kalasham a married woman of the household rather than a vessel.';
  if n <> 1 then raise exception 'Vastram, Abharanam & Mangalyam.instruction_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vastram, Abharanam & Mangalyam' and instruction_ta = 'இரண்டு வஸ்திரங்கள், பின் மாங்கல்யம், பின் ஆபரணங்கள் சமர்ப்பிக்கவும். பொதுவாக ஒரு புதிய ரவிக்கைத் துணியும், வீட்டில் உள்ள தங்க நகைகளும் பயன்படுத்தப்படுகின்றன. இந்த வரிசைதான் கலசத்தை ஒரு பாத்திரமாக அல்லாமல், வீட்டுச் சுமங்கலியாக ஆக்குகிறது.';
  if n <> 1 then raise exception 'Vastram, Abharanam & Mangalyam.instruction_ta was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Gandham, Akshatai & Pushpam' and meaning_en = 'Blended with camphor and sandal, with musk and kumkumam: receive today every fragrance, you who grant all that is auspicious. To Sri Varalakshmi, salutations: I apply the sandal, and over it I offer turmeric powder. Grains of rice, moon-white, glossy as pearls: receive these akshatai, goddess, beloved of the lotus-eyed one. With mandara, parijata and lotus, with ketaki, water-lily and patala, with jasmine, jati and vakula flowers I worship you. I offer the garland, and I worship you with flowers.';
  if n <> 1 then raise exception 'Gandham, Akshatai & Pushpam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Gandham, Akshatai & Pushpam' and philosophy_en = 'Mandara, parijata, lotus, ketaki, water-lily, patala, jasmine, jati, vakula. The verse names nine flowers, two of them from the gardens of heaven, and expects none of them in particular; it is a way of saying "the best that is in the garden".';
  if n <> 1 then raise exception 'Gandham, Akshatai & Pushpam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Anga Pooja' and instruction_ta = 'இருபத்து நான்கு நாமங்கள், ஒவ்வொன்றும் ஒரு அங்கத்தைக் குறிக்கும், பாதத்திலிருந்து சிரசு வரை; இருபத்து நான்காவது உடல் முழுவதற்கும். ஒவ்வொன்றிலும் ஒரு புஷ்பமோ சிறிது அக்ஷதையோ சமர்ப்பித்து, கலசத்தின் அல்லது படத்தின் அந்தந்த இடத்தைத் தொடவும்.';
  if n <> 1 then raise exception 'Anga Pooja.instruction_ta was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhoopam & Deepam' and meaning_en = 'I give you this pleasing incense, with guggulu and aloe: receive it, Mahalakshmi, who grant what your devotees wish. With ghee and three wicks, giver of all that is desired: receive this lamp, Kamala, and give me all that I long for. To Sri Varalakshmi, salutations: I offer the incense and show the lamp, and after them, water to sip.';
  if n <> 1 then raise exception 'Dhoopam & Deepam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Karpura Neerajanam' and meaning_en = 'This waving of light, without blemish, made by me with camphor: Lakshmi, I wave it before you, who light the worlds for ever. To Sri Varalakshmi, salutations: I show the camphor flame, and after it, water to sip.';
  if n <> 1 then raise exception 'Karpura Neerajanam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pushpanjali & Mantra Pushpam' and meaning_en = 'With jati, champaka, punnaga, jasmine, vakula and other flowers I offer you a double handful of flowers: receive it, beloved of Hari. To Sri Varalakshmi, salutations: I offer the mantra-flower; I offer the golden flower.';
  if n <> 1 then raise exception 'Pushpanjali & Mantra Pushpam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pushpanjali & Mantra Pushpam' and philosophy_en = 'Jati, jasmine and vakula were each named at the Gandham step and offered there one at a time. Here they come back in a single handful from both palms. The worship that began by itemising ends by giving everything at once.';
  if n <> 1 then raise exception 'Pushpanjali & Mantra Pushpam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pradakshina' and meaning_en = 'For the gaining of everything auspicious and the turning away of every wrong, I go round you today: be gracious, supreme goddess. Salutations to her whose face is like the lotus; salutations to the beloved of Narayana; salutations to her who was born of the ocean; salutations to Lakshmi, mother of the worlds. To Sri Varalakshmi, salutations: I offer circumambulation and prostration.';
  if n <> 1 then raise exception 'Pradakshina.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pradakshina' and philosophy_en = 'Sarvamangala labhaya, sarva papa nivrittaye, "for gaining every good, for the turning away of every wrong". The circuit asks for both in one breath, and it is recited while walking rather than sitting, so that the whole body does the asking and not only the voice.';
  if n <> 1 then raise exception 'Pradakshina.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana' and meaning_en = 'Long life, health and prosperity, sons and grandsons, cattle and wealth, and the end of enemies: grant them, Mahalakshmi, treasury of compassion. The parasol and the fan, dance, song and music, and the rest: every courtesy, those within my means and those fit for a god, I offer to you.';
  if n <> 1 then raise exception 'Namaskaram & Varalakshmi Prarthana.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana' and philosophy_en = 'Chhatra, chamara, nritta, gita, vadya: the parasol, the fan, dance, song and music, the honours of a royal court. No household has these to give, so they are offered in words. The prayer just before them is plain about what the household wants: long life, health, children and grandchildren, cattle and wealth.';
  if n <> 1 then raise exception 'Namaskaram & Varalakshmi Prarthana.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam' and meaning_en = 'Auspiciousness of all auspicious things, destroyer of every wrong: I receive this thread; be well pleased always. Of nine strands, with nine knots: let me tie this thread on my right hand, beloved of Hari.';
  if n <> 1 then raise exception 'Sharadu Dharanam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam' and philosophy_en = 'Badhniyam dakshine haste, "let me tie it on the right hand". The verb is first person, because a vidhi text is written for whoever is reciting it; it is not a ruling that the tying must be done alone. In most Tamil households the husband ties it, with three knots, and the older women tie it for the girls. Nine knots were worshipped a moment ago and three are made now, and the two counts belong to different things: the nine are the thread, the three are the tying.';
  if n <> 1 then raise exception 'Sharadu Dharanam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam' and meaning_en = 'This seat is for the brahmana, who stands here in the form of Varalakshmi; this sandal and the rest are honoured with every worship. The golden seed of fire, held within Hiranyagarbha, gives the fruit of endless merit: so grant me peace. Indira receives, and Indira indeed gives; Indira carries both across: salutations, salutations to Indira. This gift, with dakshina and with betel, I give to you, and it is no longer mine, desiring the full fruit of the Varalakshmi pooja, long and happy married life, the increase of good sons and grandsons, and the favour of Varalakshmi.';
  if n <> 1 then raise exception 'Vayana Dhanam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam' and philosophy_en = 'Indira pratigrihnati, indira vai dadati cha, "Lakshmi receives, and Lakshmi gives". The verse refuses to let either party be the superior one, which is the only way a gift between neighbours survives being ritualised.';
  if n <> 1 then raise exception 'Vayana Dhanam.philosophy_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam' and meaning_en = 'For the wearing away of every wrong I carry, for the pleasure of the supreme lord, and so that the fruit of the Varalakshmi pooja may be complete, I shall offer the arghyam of milk.';
  if n <> 1 then raise exception 'Ksheera Arghyam.meaning_en was not written'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Udvasanam' and meaning_en = 'From this vessel I return Sri Varalakshmi to her own place: for what is good, for well-being, and for her coming again.';
  if n <> 1 then raise exception 'Udvasanam.meaning_en was not written'; end if;
  select count(*) into n from public.archana_items a join public.pooja_steps s on s.id = a.pooja_step_id
   where s.pooja_id = 'varalakshmi_vratham' and s.step_title_en = 'Ksheera Arghyam'
     and a.seq = 1 and a.meaning_en = 'Mixed with cow''s milk, with sandal and flowers: receive this arghyam, goddess, giver of boons; Varalakshmi, salutations to you. To Sri Varalakshmi, salutations: this is the arghyam, this is the arghyam, this is the arghyam.';
  if n <> 1 then raise exception 'Ksheera Arghyam archana meaning was not written'; end if;

  -- Each phrase the new prose leans on is still in the mantra it describes.
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Dhyanam'
     and mantra_translit like '%vasatu gṛhe%';
  if n <> 1 then raise exception 'Dhyanam: the mantra no longer says vasatu gṛhe'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Padyam, Arghyam & Achamaniyam'
     and mantra_translit like '%madhuparkaṃ%';
  if n <> 1 then raise exception 'Padyam, Arghyam & Achamaniyam: the mantra no longer says madhuparkaṃ'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Panchamrita & Shuddhodaka Snanam'
     and mantra_translit like '%gaṅgādi saridāhṛtam%';
  if n <> 1 then raise exception 'Panchamrita & Shuddhodaka Snanam: the mantra no longer says gaṅgādi saridāhṛtam'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Gandham, Akshatai & Pushpam'
     and mantra_translit like '%mandārapārijātābjaiḥ%';
  if n <> 1 then raise exception 'Gandham, Akshatai & Pushpam: the mantra no longer says mandārapārijātābjaiḥ'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Gandham, Akshatai & Pushpam'
     and mantra_translit like '%mallikā jāti vakulaiḥ%';
  if n <> 1 then raise exception 'Gandham, Akshatai & Pushpam: the mantra no longer says mallikā jāti vakulaiḥ'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pushpanjali & Mantra Pushpam'
     and mantra_translit like '%jātī caṃpaka%';
  if n <> 1 then raise exception 'Pushpanjali & Mantra Pushpam: the mantra no longer says jātī caṃpaka'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pushpanjali & Mantra Pushpam'
     and mantra_translit like '%puṣpāñjaliṃ%';
  if n <> 1 then raise exception 'Pushpanjali & Mantra Pushpam: the mantra no longer says puṣpāñjaliṃ'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pradakshina'
     and mantra_translit like '%sarvamaṅgala lābhāya%';
  if n <> 1 then raise exception 'Pradakshina: the mantra no longer says sarvamaṅgala lābhāya'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Pradakshina'
     and mantra_translit like '%sarva pāpanivṛttaye%';
  if n <> 1 then raise exception 'Pradakshina: the mantra no longer says sarva pāpanivṛttaye'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana'
     and mantra_translit like '%cāmara%';
  if n <> 1 then raise exception 'Namaskaram & Varalakshmi Prarthana: the mantra no longer says cāmara'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Namaskaram & Varalakshmi Prarthana'
     and mantra_translit like '%āyurārogyamaiśvaryaṃ%';
  if n <> 1 then raise exception 'Namaskaram & Varalakshmi Prarthana: the mantra no longer says āyurārogyamaiśvaryaṃ'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam'
     and mantra_translit like '%badhnīyāṃ dakṣiṇe haste%';
  if n <> 1 then raise exception 'Sharadu Dharanam: the mantra no longer says badhnīyāṃ dakṣiṇe haste'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Sharadu Dharanam'
     and mantra_translit like '%navagranthi%';
  if n <> 1 then raise exception 'Sharadu Dharanam: the mantra no longer says navagranthi'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
     and mantra_translit like '%indirā pratigṛhṇāti%';
  if n <> 1 then raise exception 'Vayana Dhanam: the mantra no longer says indirā pratigṛhṇāti'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Vayana Dhanam'
     and mantra_translit like '%na mama%';
  if n <> 1 then raise exception 'Vayana Dhanam: the mantra no longer says na mama'; end if;
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham' and step_title_en = 'Ksheera Arghyam'
     and mantra_translit like '%kṣīrārghyaṃ%';
  if n <> 1 then raise exception 'Ksheera Arghyam: the mantra no longer says kṣīrārghyaṃ'; end if;

  -- Still 31 steps; prose changes must not move anything.
  select count(*) into n from public.pooja_steps where pooja_id = 'varalakshmi_vratham';
  if n <> 31 then raise exception 'varalakshmi has % steps, expected 31', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

commit;
